import Link from "next/link";

/**
 * 服务版本对比表 (改版 v10, 2026-06-29)
 *
 * 目标:
 *   - 帮助用户在 /doc-type 一眼看出"AI 智能版" vs "专家护航版" 的差别
 *   - 强化"专家护航版" 的 1对1 沟通 / 定制化 / 审核等独家价值
 *   - GEO: FAQ Schema 中的"两个版本区别"问答可引用本表
 *
 * 设计原则:
 *   - 移动端: 横向滚动表 (避免小屏挤压)
 *   - 桌面端: 标准 3 列表格, 右侧"专家护航版"高亮
 *   - 价格数字用 tabular-nums 防止抖动
 *   - 关键差异行用 ✓ / — 视觉强化
 */

interface PlanRow {
  feature: string;
  ai: string | boolean;
  expert: string | boolean;
  highlight?: boolean;
}

const ROWS: PlanRow[] = [
  { feature: "起步价", ai: "¥19.9", expert: "¥199", highlight: true },
  { feature: "预计完成时间", ai: "10 分钟", expert: "1-3 个工作日" },
  { feature: "智能问卷生成草稿", ai: true, expert: true },
  { feature: "《民法典》条款引用与核查", ai: true, expert: true },
  { feature: "PDF + Word 双格式下载", ai: true, expert: true },
  { feature: "1 对 1 资产规划专业人士视频沟通", ai: false, expert: true, highlight: true },
  { feature: "基于您具体情况的定制化条款建议", ai: false, expert: true, highlight: true },
  { feature: "专业人士逐条审阅 + 修订建议", ai: false, expert: true },
  { feature: "7 天内不限次修改", ai: false, expert: true },
  { feature: "签署后 30 天内合规咨询", ai: false, expert: true },
  { feature: "适用场景", ai: "通用模板已能覆盖", expert: "资产复杂 / 再婚 / 多代传承" },
];

function Cell({ value, highlight }: { value: string | boolean; highlight?: boolean }) {
  if (typeof value === "boolean") {
    return value ? (
      <span className="text-emerald-600 font-bold" aria-label="包含">✓</span>
    ) : (
      <span className="text-slate-300" aria-label="不包含">—</span>
    );
  }
  return <span className={highlight ? "font-semibold text-amber-700" : "text-slate-700"}>{value}</span>;
}

export function PlanComparisonTable({ defaultType = "will" }: { defaultType?: string }) {
  return (
    <section
      aria-labelledby="plan-comparison-title"
      className="mt-12 sm:mt-16 scroll-mt-24"
      id="pricing"
    >
      <div className="text-center mb-6">
        <span className="inline-block bg-amber-100 text-amber-700 text-xs px-2 py-1 rounded-full mb-2 font-medium">
          <span aria-hidden>💎 </span>两个版本怎么选
        </span>
        <h2 id="plan-comparison-title" className="text-2xl sm:text-3xl font-bold text-slate-800 text-balance">
          智能版 vs 专家护航版
        </h2>
        <p className="text-slate-600 mt-2 max-w-2xl mx-auto text-sm sm:text-base leading-relaxed-cn">
          先用智能版快速出草稿, 若情况复杂 (再婚 / 多套房产 / 跨境资产 / 多代传承) 再升级到专家护航。
        </p>
      </div>

      <div className="overflow-x-auto -mx-4 px-4 pb-2">
        <table className="w-full min-w-[640px] border-collapse bg-white rounded-2xl shadow-sm overflow-hidden">
          <thead>
            <tr className="bg-slate-50 border-b-2 border-slate-200">
              <th
                scope="col"
                className="text-left text-sm font-medium text-slate-600 px-4 py-3 w-[36%]"
              >
                对比项
              </th>
              <th
                scope="col"
                className="text-center text-sm font-bold text-slate-700 px-4 py-3 w-[32%]"
              >
                智能版
                <div className="text-xs font-normal text-slate-500 mt-0.5">¥19.9 起</div>
              </th>
              <th
                scope="col"
                className="text-center text-sm font-bold text-amber-700 bg-amber-50 px-4 py-3 w-[32%] border-l-2 border-r-2 border-amber-300"
              >
                <span aria-hidden>⭐ </span>专家护航版
                <div className="text-xs font-normal text-amber-600 mt-0.5">¥199 起</div>
              </th>
            </tr>
          </thead>
          <tbody>
            {ROWS.map((row, i) => (
              <tr
                key={row.feature}
                className={
                  i % 2 === 0
                    ? "bg-white"
                    : "bg-slate-50/50"
                }
              >
                <th
                  scope="row"
                  className="text-left text-sm text-slate-700 px-4 py-3 font-medium border-t border-slate-100"
                >
                  {row.feature}
                </th>
                <td className="text-center text-sm px-4 py-3 border-t border-slate-100">
                  <Cell value={row.ai} highlight={row.highlight} />
                </td>
                <td className="text-center text-sm px-4 py-3 border-t border-slate-100 bg-amber-50/40 border-l-2 border-r-2 border-amber-200">
                  <Cell value={row.expert} highlight={row.highlight} />
                </td>
              </tr>
            ))}
            <tr>
              <td className="px-4 py-4" />
              <td className="px-4 py-4 text-center">
                <Link
                  href={`/questionnaire?type=${defaultType}&plan=ai`}
                  className="inline-block border-2 border-amber-500 text-amber-600 hover:bg-amber-500 hover:text-white px-4 py-2 rounded-lg text-sm font-semibold transition"
                >
                  用智能版开始
                </Link>
              </td>
              <td className="px-4 py-4 text-center bg-amber-50/40 border-l-2 border-r-2 border-b-2 border-amber-300 rounded-b-2xl">
                <Link
                  href={`/questionnaire?type=${defaultType}&plan=expert`}
                  className="inline-block bg-amber-500 hover:bg-amber-600 text-white px-4 py-2 rounded-lg text-sm font-semibold transition shadow-sm"
                >
                  约专家 1 对 1
                </Link>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <p className="text-xs text-slate-500 mt-3 text-center leading-relaxed-cn">
        价格透明, 无隐藏费用 · 7 天无理由退款 · 不满意全额退
      </p>
    </section>
  );
}
